module.exports = {
  siteMetadata: {
    title: `Something Cool`,
    description: `A wonderful thing indeed.`,
    author: `@gatsbyjs`,
  },
  plugins: [
    `gatsby-plugin-react-helmet`,
    {
      resolve: `gatsby-source-filesystem`,
      options: {
        name: `images`,
        path: `${__dirname}/src/images`,
      },
    },
    {
      resolve: 'gatsby-source-filesystem',
      options: {
        name: 'pageMarkdown',
        path: `${__dirname}/src/markdown/pages/`,
      },
    },
    {
