        name: `gatsby-starter-default`,
        short_name: `starter`,
        start_url: `/`,
        background_color: `#663399`,
        theme_color: `#663399`,
        display: `minimal-ui`,
        icon: `src/images/gatsby-icon.png`, // This path is relative to the root of the site.
      },
    },
    // this (optional) plugin enables Progressive Web App + Offline functionality
    // To learn more, visit: https://gatsby.app/offline
    // 'gatsby-plugin-offline',
  ],
};

const path = require('path');

const template = path.resolve('./src/templates/page.js');

/**
 * Implement Gatsby's Node APIs in this file.
 *
 * See: https://www.gatsbyjs.org/docs/node-apis/
 */

exports.createPages = ({ graphql, actions }) => {
  const { createPage } = actions;
  return new Promise((resolve, reject) => {
    resolve(
      graphql(
        `
          {
            allMarkdownRemark(limit: 1000) {
              edges {
                node {
                  frontmatter {
                    title
                    path
                    type
                  }
                  rawMarkdownBody
                  html
                }
              }
            }
          }
        `,
      ).then(result => {
        if (result.errors) {
          reject(result.errors);
          return;
        }
        result.data.allMarkdownRemark.edges.forEach(({ node }) => {
          if (node.frontmatter.path) {
            createPage({
              path: node.frontmatter.path,
              component: template,
              context: {
                markdown: node.rawMarkdownBody,
                html: node.html,
              },
            });
          }
        });
      }),
    );
  });
};

import React from 'react';
import PropTypes from 'prop-types';
import Helmet from 'react-helmet';
import { StaticQuery, graphql } from 'gatsby';

function SEO({ description, lang, meta, keywords, title }) {
  return (
    <StaticQuery
      query={detailsQuery}
      render={data => {
        const metaDescription =
          description || data.markdownRemark.frontmatter.siteDescription;
        return (
          <Helmet
            htmlAttributes={{
              lang,
            }}
            title={title}
            titleTemplate={`%s | ${data.markdownRemark.frontmatter.siteName}`}
            meta={[
              {
                name: `description`,
                content: metaDescription,
              },
              {
                property: `og:title`,
                content: title,
              },
              {
                property: `og:description`,
                content: metaDescription,
              },
              {
                property: `og:type`,
                content: `website`,
              },
              {
                name: `twitter:card`,
                content: `summary`,
              },
              {
                name: `twitter:creator`,
                content: data.site.siteMetadata.author,
              },
              {
                name: `twitter:title`,
                content: title,
              },
              {
                name: `twitter:description`,
                content: metaDescription,
              },
            ]
              .concat(
                keywords.length > 0
                  ? {
                      name: `keywords`,
                      content: keywords.join(`, `),
                    }
                  : [],
              )
              .concat(meta)}
          />
        );
      }}
    />
  );
}

SEO.defaultProps = {
  lang: `en`,
  meta: [],
  keywords: [],
};

SEO.propTypes = {
  description: PropTypes.string,
  lang: PropTypes.string,
  meta: PropTypes.array,
  keywords: PropTypes.arrayOf(PropTypes.string),
  title: PropTypes.string.isRequired,
};

export default SEO;

const detailsQuery = graphql`
  {
    markdownRemark(frontmatter: { type: { eq: "config" } }) {
      frontmatter {
        siteName
        siteDescription
      }
    }
    site {
      siteMetadata {
        author
      }
    }
  }
`;

import React from 'react';
import { StaticQuery, graphql } from 'gatsby';

/* eslint-disable react/prop-types */
export default ({ children }) => {
  return (
    <StaticQuery
      query={graphql`
        {
          markdownRemark(frontmatter: { type: { eq: "config" } }) {
            id
            frontmatter {
              primaryColor
              bodyTextColor
              headerTextColor
              bodyFontFamily
              headerFontFamily
            }
          }
        }
      `}
      render={data => {
        const theme = data.markdownRemark.frontmatter;
        return children(theme);
      }}
    />
  );
};

import { Link, StaticQuery, graphql } from 'gatsby';
import PropTypes from 'prop-types';
import React from 'react';
import styled from 'styled-components';
import Theme from './Theme';

const Header = ({ siteTitle }) => (
  <Theme>
    {({ primaryColor }) => (
      <div
        style={{
          background: primaryColor,
          marginBottom: `1.45rem`,
        }}
      >
        <div
          style={{
            margin: `0 auto`,
            maxWidth: 960,
            padding: `1.45rem 1.0875rem`,
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}
        >
          <h3 style={{ margin: 0 }}>
            <Link
              to="/"
              style={{
                color: `white`,
                textDecoration: `none`,
              }}
            >
              {siteTitle}
            </Link>
          </h3>
          <StaticQuery
            query={graphql`
              {
                allMarkdownRemark(limit: 1000) {
                  edges {
                    node {
                      id
                      frontmatter {
                        title
                        path
                        type
                      }
                    }
                  }
                }
              }
            `}
            render={data => (
              <Nav>
                {data.allMarkdownRemark.edges
                  .filter(({ node }) => node.frontmatter.type !== 'config')
                  .map(({ node }) => (
                    <h4 key={node.id} style={{ margin: 10 }}>
                      <Link
                        style={{
                          color: `white`,
                          textDecoration: `none`,
                        }}
                        to={node.frontmatter.path}
                      >
                        {node.frontmatter.title}
                      </Link>
                    </h4>
                  ))}
              </Nav>
            )}
          />
        </div>
      </div>
    )}
  </Theme>
);

Header.propTypes = {
  siteTitle: PropTypes.string,
};

Header.defaultProps = {
  siteTitle: ``,
};

export default Header;

const Nav = styled.nav`
  margin: 10px;
  display: flex;
  justify-content: space-between;
  overflow-x: auto;
  overflow-y: hidden;
  @media (max-width: 450px) {
    mask-image: -webkit-linear-gradient(
      to right,
      transparent,
      black 20px,
      black 90%,
      transparent
    );
    mask-image: -moz-linear-gradient(
      to right,
      transparent,
      black 20px,
      black 90%,
      transparent
    );
    mask-image: linear-gradient(
      to right,
      transparent,
      black 20px,
      black 90%,
      transparent
    );
    -webkit-mask-image: -webkit-linear-gradient(
      to right,
      transparent,
      black 20px,
      black 90%,
      transparent
    );
    -webkit-mask-image: -moz-linear-gradient(
      to right,
      transparent,
      black 20px,
      black 90%,
      transparent
    );
    -webkit-mask-image: linear-gradient(
      to right,
      transparent,
      black 20px,
      black 90%,
      transparent
    );
  }
`;

import React from 'react';
import PropTypes from 'prop-types';
import styled from 'styled-components';
import { StaticQuery, graphql } from 'gatsby';

import Header from './header';
import './layout.css';
import Theme from './Theme';

const Layout = ({ children }) => (
  <StaticQuery
    query={graphql`
      query SiteTitleQuery {
        markdownRemark(frontmatter: { type: { eq: "config" } }) {
          frontmatter {
            siteName
          }
        }
      }
    `}
    render={data => (
      <>
        <Theme>
          {theme => (
            <Container {...theme}>
              <Header siteTitle={data.markdownRemark.frontmatter.siteName} />
              <div
                style={{
                  margin: `0 auto`,
                  maxWidth: 960,
                  padding: `0px 1.0875rem 1.45rem`,
                  paddingTop: 0,
                }}
              >
                {children}
              </div>
            </Container>
          )}
        </Theme>
      </>
    )}
  />
);

Layout.propTypes = {
  children: PropTypes.node.isRequired,
};

export default Layout;

const Container = styled.div`
  * {
    color: ${props => props.bodyTextColor};
    font-family: ${props => props.bodyFontFamily};
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: ${props => props.headerTextColor};
    font-family: ${props => props.headerFontFamily};
  }
`;

import React from 'react';
import PropTypes from 'prop-types';

class AsyncLoadInlineImage extends React.PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      hasLoaded: false,
      loadAsync: true,
    };
  }

  componentDidMount() {
    const { src } = this.props;
    this.img = new Image();
    this.img.onload = () => {
      this.setState({ hasLoaded: true });
    };
    this.img.src = src;
    if (this.img.complete) {
      this.setState({ hasLoaded: true, loadAsync: false });
    }
  }

  /* eslint-disable jsx-a11y/alt-text */
  render() {
    const { hasLoaded, loadAsync } = this.state;
    return (
      <img
        {...this.props}
        style={{
          opacity: !hasLoaded && loadAsync ? 0 : 1,
          transition: '0.75s all',
          backgroundColor: '#fafafa',
        }}
      />
    );
  }
}

AsyncLoadInlineImage.propTypes = {
  src: PropTypes.string.isRequired,
};

export default AsyncLoadInlineImage;

import React from 'react';

import Layout from '../components/layout';
import SEO from '../components/seo';

const NotFoundPage = () => (
  <Layout>
    <SEO title="404: Not found" />
    <h1>NOT FOUND</h1>
    <p>You just hit a route that doesn&#39;t exist... the sadness.</p>
  </Layout>
);

export default NotFoundPage;

import React from 'react';
import ReactMarkdown from 'react-markdown';

import AsyncLoadInlineImage from '../components/AsyncLoadInlineImage';
import Layout from '../components/layout';
import SEO from '../components/seo';

const IndexPage = props => {
  return (
    <Layout>
      <SEO
        title={props.pageContext.title}
        keywords={props.pageContext.keywords}
      />
      <ReactMarkdown
        source={props.pageContext.markdown}
        renderers={{
          image: imageProps => {
            return <AsyncLoadInlineImage {...imageProps} />;
          },
        }}
      />
    </Layout>
  );
};

export default IndexPage;
